// Package credentials loads sensitive values that must never be written
// to the GitOps repo. See docs/decisions/0012-platform-config-and-credentials.md
// in urbforge/urbex: environment variables take precedence, falling back
// to ~/.urbex/credentials.yaml.
//
// Some values are supplied by the user (Proxmox/Cloudflare tokens, age
// key); the platform secrets (admin passwords, Komodo API and onboarding
// keys, the forge's token) are generated by urbex bootstrap and persisted to the same file
// via Update.
package credentials

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

// Credentials holds secrets read from the environment or from
// ~/.urbex/credentials.yaml. Never log or serialize this back out, except
// through Update.
type Credentials struct {
	ProxmoxToken    string `yaml:"proxmoxToken,omitempty"`
	CloudflareToken string `yaml:"cloudflareToken,omitempty"`
	AgeKey          string `yaml:"ageKey,omitempty"`
	// Where Grafana sends the alerts (observability.alerts in the
	// platform config, urbforge/urbex-cli#95): provided by the user.
	TelegramBotToken  string `yaml:"telegramBotToken,omitempty"`
	DiscordWebhookURL string `yaml:"discordWebhookUrl,omitempty"`
	AlertsWebhookURL  string `yaml:"alertsWebhookUrl,omitempty"`
	// ProxmoxMonitorToken is a read-only (PVEAuditor) token of the whole
	// node, "user@realm!name=secret", for the node's metrics in Grafana
	// (urbforge/urbex-cli#94); optional, provided by the user.
	ProxmoxMonitorToken string `yaml:"proxmoxMonitorToken,omitempty"`
	// ProxmoxBackupToken is the token the platform backs its machines up
	// with (ADR-0036's Proxmox layer, urbforge/urbex-cli#121): Pool.Audit,
	// VM.Audit and VM.Backup on the pool, Datastore.AllocateSpace and
	// Datastore.Audit on backups.proxmox.storage, nothing else. It is the
	// one Proxmox token kept on the platform, in Komodo; optional,
	// provided by the user.
	ProxmoxBackupToken string `yaml:"proxmoxBackupToken,omitempty"`
	// The file layer's bucket (backups.files.target, s3:...): its access
	// key, provided by the user. Kept on the platform, in Komodo.
	BackupS3AccessKeyID     string `yaml:"backupS3AccessKeyId,omitempty"`
	BackupS3SecretAccessKey string `yaml:"backupS3SecretAccessKey,omitempty"`
	// BackupPassword encrypts the file layer's restic repository
	// (urbforge/urbex-cli#122). Generated by urbex bootstrap, printed
	// once: the operator keeps it off the platform, with the age key.
	// Never cleared - a platform torn down and created again must still
	// read its backups.
	BackupPassword string `yaml:"backupPassword,omitempty"`
	// BackupSecretsStored is "yes" once the operator has stored the age
	// key and BackupPassword off the platform; urbex doctor warns until
	// then.
	BackupSecretsStored string `yaml:"backupSecretsStored,omitempty"`

	// Generated by urbex bootstrap.
	ForgeAdminPassword      string `yaml:"forgeAdminPassword,omitempty"`
	ForgeToken              string `yaml:"forgeToken,omitempty"`
	KomodoAdminPassword     string `yaml:"komodoAdminPassword,omitempty"`
	KomodoDBPassword        string `yaml:"komodoDbPassword,omitempty"`
	KomodoJWTSecret         string `yaml:"komodoJwtSecret,omitempty"`
	KomodoWebhookSecret     string `yaml:"komodoWebhookSecret,omitempty"`
	KomodoAPIKey            string `yaml:"komodoApiKey,omitempty"`
	KomodoAPISecret         string `yaml:"komodoApiSecret,omitempty"`
	KomodoOnboardingKey     string `yaml:"komodoOnboardingKey,omitempty"`
	KeycloakAdminPassword   string `yaml:"keycloakAdminPassword,omitempty"`
	KeycloakDBPassword      string `yaml:"keycloakDbPassword,omitempty"`
	GrafanaAdminPassword    string `yaml:"grafanaAdminPassword,omitempty"`
	TechnitiumAdminPassword string `yaml:"technitiumAdminPassword,omitempty"`
	TechnitiumToken         string `yaml:"technitiumToken,omitempty"`
}

// fields pairs every credential with its environment variable, so Load,
// fillFrom, and Env stay in sync as credentials are added.
func (c *Credentials) fields() []struct {
	env string
	ptr *string
} {
	return []struct {
		env string
		ptr *string
	}{
		{"URBEX_PROXMOX_TOKEN", &c.ProxmoxToken},
		{"URBEX_CLOUDFLARE_TOKEN", &c.CloudflareToken},
		{"URBEX_AGE_KEY", &c.AgeKey},
		{"URBEX_TELEGRAM_BOT_TOKEN", &c.TelegramBotToken},
		{"URBEX_DISCORD_WEBHOOK_URL", &c.DiscordWebhookURL},
		{"URBEX_ALERTS_WEBHOOK_URL", &c.AlertsWebhookURL},
		{"URBEX_PROXMOX_MONITOR_TOKEN", &c.ProxmoxMonitorToken},
		{"URBEX_PROXMOX_BACKUP_TOKEN", &c.ProxmoxBackupToken},
		{"URBEX_BACKUP_S3_ACCESS_KEY_ID", &c.BackupS3AccessKeyID},
		{"URBEX_BACKUP_S3_SECRET_ACCESS_KEY", &c.BackupS3SecretAccessKey},
		{"URBEX_BACKUP_PASSWORD", &c.BackupPassword},
		{"URBEX_BACKUP_SECRETS_STORED", &c.BackupSecretsStored},
		{"URBEX_FORGE_ADMIN_PASSWORD", &c.ForgeAdminPassword},
		{"URBEX_FORGE_TOKEN", &c.ForgeToken},
		{"URBEX_KOMODO_ADMIN_PASSWORD", &c.KomodoAdminPassword},
		{"URBEX_KOMODO_DB_PASSWORD", &c.KomodoDBPassword},
		{"URBEX_KOMODO_JWT_SECRET", &c.KomodoJWTSecret},
		{"URBEX_KOMODO_WEBHOOK_SECRET", &c.KomodoWebhookSecret},
		{"URBEX_KOMODO_API_KEY", &c.KomodoAPIKey},
		{"URBEX_KOMODO_API_SECRET", &c.KomodoAPISecret},
		{"URBEX_KOMODO_ONBOARDING_KEY", &c.KomodoOnboardingKey},
		{"URBEX_KEYCLOAK_ADMIN_PASSWORD", &c.KeycloakAdminPassword},
		{"URBEX_KEYCLOAK_DB_PASSWORD", &c.KeycloakDBPassword},
		{"URBEX_GRAFANA_ADMIN_PASSWORD", &c.GrafanaAdminPassword},
		{"URBEX_TECHNITIUM_ADMIN_PASSWORD", &c.TechnitiumAdminPassword},
		{"URBEX_TECHNITIUM_TOKEN", &c.TechnitiumToken},
	}
}

// legacyNames are the names of the forge's credentials before it was
// Forgejo (docs/decisions/0034-forgejo-lts-forge.md in urbforge/urbex):
// still read, from the environment and from credentials.yaml, so that a
// workspace written by urbex 0.1.0 works unchanged. The new names win.
var legacyNames = map[string]struct{ env, key string }{
	"URBEX_FORGE_ADMIN_PASSWORD": {"URBEX_GITEA_ADMIN_PASSWORD", "giteaAdminPassword"},
	"URBEX_FORGE_TOKEN":          {"URBEX_GITEA_TOKEN", "giteaToken"},
}

// canonical is the current name of the credential whose environment
// variable is name, which may be a legacy one.
func canonical(name string) string {
	for current, old := range legacyNames {
		if name == old.env {
			return current
		}
	}
	return name
}

// Load reads credentials from environment variables first (URBEX_*, see
// fields; legacy names too), then fills in anything still missing from
// ~/.urbex/credentials.yaml if that file exists.
func Load() (*Credentials, error) {
	c := &Credentials{}
	for _, f := range c.fields() {
		*f.ptr = os.Getenv(f.env)
		if old, ok := legacyNames[f.env]; ok && *f.ptr == "" {
			*f.ptr = os.Getenv(old.env)
		}
	}
	path, err := DefaultPath()
	if err != nil {
		return nil, err
	}
	fromFile, err := loadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return c, nil
		}
		return nil, err
	}
	c.fillFrom(fromFile)
	return c, nil
}

// DefaultPath returns ~/.urbex/credentials.yaml for the current user.
func DefaultPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("determining home directory: %w", err)
	}
	return filepath.Join(home, ".urbex", "credentials.yaml"), nil
}

// HostWorkspaceEnv names the host folder urbex-op mounts on
// containerWorkspace (tools/operator/urbex-op sets it).
const (
	HostWorkspaceEnv   = "URBEX_HOST_WORKSPACE"
	containerWorkspace = "/work"
)

// HostPath is path as the user finds it on their machine: under urbex-op
// a path in the container's workspace becomes the host folder's, so that
// the paths urbex prints can be opened. Elsewhere it is path unchanged.
func HostPath(path string) string {
	host := os.Getenv(HostWorkspaceEnv)
	if host == "" {
		return path
	}
	rel, err := filepath.Rel(containerWorkspace, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		return path
	}
	return filepath.Join(host, rel)
}

func loadFile(path string) (*Credentials, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Credentials
	if err := yaml.Unmarshal(data, &c); err != nil {
		return nil, fmt.Errorf("parsing %s: %w", path, err)
	}
	// The legacy keys fill what the new ones leave empty; the next Update
	// writes them under the new keys.
	var all map[string]any
	if err := yaml.Unmarshal(data, &all); err == nil {
		for _, f := range c.fields() {
			if old, ok := legacyNames[f.env]; ok && *f.ptr == "" {
				if v, ok := all[old.key].(string); ok {
					*f.ptr = v
				}
			}
		}
	}
	return &c, nil
}

func (c *Credentials) fillFrom(other *Credentials) {
	theirs := other.fields()
	for i, f := range c.fields() {
		if *f.ptr == "" {
			*f.ptr = *theirs[i].ptr
		}
	}
}

// Update applies change to both c and the credentials file (creating it
// with mode 0600 if needed), leaving every other value in the file as it
// was - values that came from the environment are not copied into it.
func (c *Credentials) Update(change func(*Credentials)) error {
	path, err := DefaultPath()
	if err != nil {
		return err
	}
	onDisk, err := loadFile(path)
	if os.IsNotExist(err) {
		onDisk = &Credentials{}
	} else if err != nil {
		return err
	}
	change(c)
	change(onDisk)
	data, err := yaml.Marshal(onDisk)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	if err := os.WriteFile(path, data, 0o600); err != nil {
		return err
	}
	// WriteFile keeps an existing file's mode; make sure it's private.
	return os.Chmod(path, 0o600)
}

// Get returns the credential whose environment variable is name, or ""
// if name isn't a known credential.
func (c *Credentials) Get(name string) string {
	name = canonical(name)
	for _, f := range c.fields() {
		if f.env == name {
			return *f.ptr
		}
	}
	return ""
}

// Set sets the credential whose environment variable is name; unknown
// names are ignored.
func (c *Credentials) Set(name, value string) {
	name = canonical(name)
	for _, f := range c.fields() {
		if f.env == name {
			*f.ptr = value
		}
	}
}

// Env returns URBEX_*=value entries for the given credentials, for
// passing secrets to child processes (e.g. Ansible's lookup('env')) without
// writing them to files.
func (c *Credentials) Env(names ...string) []string {
	want := make(map[string]bool, len(names))
	for _, n := range names {
		want[canonical(n)] = true
	}
	var env []string
	for _, f := range c.fields() {
		if want[f.env] {
			env = append(env, f.env+"="+*f.ptr)
		}
	}
	return env
}

// RandomSecret returns a random 48-hex-character secret, safe to use
// unquoted in env files and shell arguments.
func RandomSecret() (string, error) {
	b := make([]byte, 24)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// MissingForProvisioning reports which credentials required for the
// Terraform+Ansible provisioning phase of urbex bootstrap are missing.
// The Cloudflare token is needed only by a later phase (tunnel setup)
// and is checked separately once that is implemented; platform secrets
// are generated by bootstrap itself.
func (c *Credentials) MissingForProvisioning() []string {
	var missing []string
	if c.ProxmoxToken == "" {
		missing = append(missing, "URBEX_PROXMOX_TOKEN (or proxmoxToken in ~/.urbex/credentials.yaml)")
	}
	if c.AgeKey == "" {
		missing = append(missing, "URBEX_AGE_KEY (or ageKey in ~/.urbex/credentials.yaml)")
	}
	return missing
}

// MissingForPlatform reports which bootstrap-generated credentials needed
// to set up and run project rollouts (the forge, Komodo) are missing - i.e.
// whether urbex bootstrap has completed on this machine.
func (c *Credentials) MissingForPlatform() []string {
	var missing []string
	for _, f := range []struct {
		env string
		v   string
	}{
		{"URBEX_FORGE_TOKEN", c.ForgeToken},
		{"URBEX_KOMODO_API_KEY", c.KomodoAPIKey},
		{"URBEX_KOMODO_API_SECRET", c.KomodoAPISecret},
		{"URBEX_KOMODO_ONBOARDING_KEY", c.KomodoOnboardingKey},
		{"URBEX_KOMODO_WEBHOOK_SECRET", c.KomodoWebhookSecret},
	} {
		if f.v == "" {
			missing = append(missing, f.env)
		}
	}
	return missing
}

// provided are the credentials the user supplies, and the backup
// password, which outlives a platform; every other one is generated by
// urbex bootstrap for the platform it creates, and cleared with it.
var provided = map[string]bool{
	"URBEX_PROXMOX_TOKEN":    true,
	"URBEX_CLOUDFLARE_TOKEN": true,
	"URBEX_AGE_KEY":          true,
	// The alerts' channels.
	"URBEX_TELEGRAM_BOT_TOKEN":  true,
	"URBEX_DISCORD_WEBHOOK_URL": true,
	"URBEX_ALERTS_WEBHOOK_URL":  true,
	// The node's metrics.
	"URBEX_PROXMOX_MONITOR_TOKEN": true,
	// The Proxmox layer of the backups.
	"URBEX_PROXMOX_BACKUP_TOKEN": true,
	// The file layer: the bucket's key; and the backup password, which
	// bootstrap generates but which must outlive the platform: without
	// it the backups can't be read.
	"URBEX_BACKUP_S3_ACCESS_KEY_ID":     true,
	"URBEX_BACKUP_S3_SECRET_ACCESS_KEY": true,
	"URBEX_BACKUP_PASSWORD":             true,
	"URBEX_BACKUP_SECRETS_STORED":       true,
}

// ClearGenerated forgets every credential urbex bootstrap generated -
// passwords, tokens, keys of a platform that no longer exists - in memory
// and in ~/.urbex/credentials.yaml, so the next bootstrap generates new
// ones. The credentials the user supplies are kept.
func (c *Credentials) ClearGenerated() error {
	return c.Update(func(target *Credentials) {
		for _, f := range target.fields() {
			if !provided[f.env] {
				*f.ptr = ""
			}
		}
	})
}
